INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('wayanad', 'Wayanad', '["Edakkal Caves","Waterfalls","Plantations"]', 'Drive into Wayanad through ghats and spice country. Check in and spend the evening at leisure among the plantations.', 'Visit Edakkal Caves, Soochipara or Meenmutty Falls, and a viewpoint such as Banasura. Optional Chembra or trekking on request. Evening at leisure.', '["forest.jpg","camping.jpg","hills-mist.jpg","waterfall.jpg","mountains.jpg"]', 0);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('kozhikode', 'Kozhikode', '["Kappad Beach","City markets","Coast"]', 'Continue to Kozhikode. Check in and stroll the beach or SM Street in the evening.', 'Explore Kappad Beach, city markets and a relaxed coastal evening. Optional Beypore or temple stop on request.', '["beach.jpg","goa-beach.jpg","city.jpg","village.jpg"]', 1);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('mysore', 'Mysore', '["Mysore Palace","Gardens","Markets"]', 'Drive to Mysore. Check in and visit the illuminated palace precincts or Devaraja Market if time allows.', 'Visit Mysore Palace, Chamundi Hills and Brindavan Gardens. Evening at leisure in the royal city.', '["temple.jpg","rajasthan.jpg","city.jpg","resort.jpg"]', 2);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('ooty', 'Ooty', '["Nilgiri hills","Botanical garden","Tea estates"]', 'Climb into the Nilgiris. Check in at Ooty and enjoy a cool evening at leisure.', 'Visit the Botanical Garden, Ooty Lake, Doddabetta or a tea estate. Optional toy-train stretch subject to availability.', '["waterfall.jpg","hills-mist.jpg","tea-plantation.jpg","lake.jpg","mountains.jpg"]', 3);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('coorg', 'Coorg', '["Coffee estates","Abbey Falls","Madikeri"]', 'Drive into Coorg’s coffee hills. Check in around Madikeri and ease into the evening.', 'Visit Abbey Falls, Raja’s Seat, a coffee plantation and Madikeri Fort. Local Kodava meals on request.', '["forest.jpg","tea-plantation.jpg","waterfall.jpg","village.jpg","resort.jpg"]', 4);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('chikmagalur', 'Chikmagalur', '["Mullayanagiri","Coffee hills","Viewpoints"]', 'Continue to Chikmagalur. Check in and enjoy a quiet hill evening.', 'Visit Mullayanagiri or Baba Budangiri viewpoints and a coffee estate. Pace stays gentle in the hills.', '["hills-mist.jpg","mountains.jpg","tea-plantation.jpg","camping.jpg"]', 5);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('munnar', 'Munnar', '["Tea gardens","Viewpoints","Eravikulam"]', 'Scenic drive to Munnar with photo stops. Check in and spend the evening in the tea hills.', 'Visit tea plantations, a viewpoint such as Top Station or Echo Point, and the tea museum. Eravikulam subject to park rules.', '["tea-plantation.jpg","hills-mist.jpg","mountains.jpg","waterfall.jpg","lake.jpg"]', 6);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('thekkady', 'Thekkady', '["Periyar","Spice gardens","Wildlife"]', 'Drive to Thekkady. Spice garden visit and evening at leisure by the sanctuary.', 'Spice plantation walk and optional Periyar boat safari or cultural show, subject to availability.', '["forest.jpg","lake.jpg","camping.jpg","village.jpg"]', 7);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('gavi', 'Gavi', '["Gavi forest","Wildlife","Bamboo raft"]', 'Head into the Gavi forest belt. Check in at a simple forest stay if included, or return to Thekkady by evening.', 'Guided forest trail and optional bamboo rafting / wildlife watching in the Gavi–Vallakadavu belt, subject to permits.', '["camping.jpg","forest.jpg","lake.jpg","mountains.jpg"]', 8);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('alleppey', 'Alleppey', '["Houseboat","Backwaters","Village life"]', 'Board a houseboat or check in by the backwaters. Cruise the canals, enjoy onboard meals and a slow sunset.', 'Village walk, canal cruise or a second stretch on the water. Unhurried backwater morning before onward travel.', '["kerala-backwaters.jpg","lake.jpg","village.jpg","resort-pool.jpg"]', 9);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('athirappilly', 'Athirappilly', '["Athirappilly Falls","Vazhachal","River forest"]', 'Drive to Athirappilly. Check in near the falls and visit the viewpoint in the evening if light allows.', 'Athirappilly and Vazhachal Falls with forest-edge walks. Optional river-bank time before checkout.', '["waterfall.jpg","forest.jpg","camping.jpg","mountains.jpg"]', 10);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('kochi', 'Kochi', '["Fort Kochi","Chinese nets","Harbour city"]', 'Arrive in Kochi. Check in and explore Fort Kochi — Chinese fishing nets, harbour walk and cafe streets — at an easy pace.', 'Fort Kochi heritage walk, Mattancherry / Jew Town and a relaxed harbour evening. Optional Kathakali on request.', '["city.jpg","beach.jpg","friends-travel.jpg","resort.jpg"]', 11);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('vagamon', 'Vagamon', '["Meadows","Pine forest","Viewpoints"]', 'Climb to Vagamon. Check in and enjoy meadow and pine-forest views in the evening.', 'Vagamon meadows, pine forest and a viewpoint such as Thangal para. Optional paragliding in season.', '["hills-mist.jpg","mountains.jpg","camping.jpg","tea-plantation.jpg"]', 12);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('varkala', 'Varkala', '["Cliff beach","Arabian Sea","Sunset"]', 'Drive to Varkala. Check in near the cliff and walk the promenade for sunset.', 'Papanasam Beach, cliff cafes and a leisurely sea morning. Optional spring or temple visit.', '["beach.jpg","goa-beach.jpg","couple-travel.jpg","resort-pool.jpg"]', 13);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('kovalam', 'Kovalam', '["Lighthouse beach","Coast","Ayurveda"]', 'Continue to Kovalam. Check in and spend the evening on the crescent beaches.', 'Lighthouse Beach and a slow coastal day. Optional Ayurveda session on request.', '["goa-beach.jpg","beach.jpg","resort-pool.jpg","maldives.jpg"]', 14);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('trivandrum', 'Trivandrum', '["Padmanabhaswamy","Kovalam coast","City"]', 'Drive to Trivandrum. Check in and visit the temple precincts or Shanghumugham if time allows.', 'Padmanabhaswamy Temple (dress code applies), Napier Museum area or a short coastal stop before onward travel.', '["temple.jpg","city.jpg","beach.jpg","rajasthan.jpg"]', 15);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('valparai', 'Valparai', '["Tea estates","Wildlife","Hairpin ghats"]', 'Climb the Valparai ghats through tea estates. Check in and watch for lion-tailed macaques along the estate roads.', 'Estate viewpoints, Sholayar or Nallamudi and a gentle wildlife drive. Cool evenings in the Anamalais.', '["tea-plantation.jpg","forest.jpg","hills-mist.jpg","mountains.jpg"]', 16);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('kodaikanal', 'Kodaikanal', '["Kodai Lake","Coaker’s Walk","Pine forest"]', 'Drive up to Kodaikanal. Check in and walk Coaker’s Walk or the lake in the evening.', 'Kodai Lake, Coaker’s Walk, Pillar Rocks or a pine-forest trail. Optional boat ride on the lake.', '["lake.jpg","hills-mist.jpg","mountains.jpg","waterfall.jpg"]', 17);
INSERT INTO places (slug, label, tags_json, arrive_text, sightseeing_text, images_json, sort_order) VALUES ('lakshadweep', 'Lakshadweep', '["Lagoon","Snorkel","Island stay"]', 'Fly to Agatti (permits required). Transfer to your island stay and settle into lagoon time.', 'Lagoon snorkelling, beach walks and a slow island day. Water sports as permitted for your island.', '["island.jpg","maldives.jpg","beach.jpg","resort-pool.jpg"]', 18);
