INSERT INTO page_content (page_key, title, sections_json) VALUES ('home', 'Home', '{"hero_title":"Travel, nested with care","hero_text":"Curated Kerala and South Indian journeys, stays and experiences — pricing shared personally after you enquire.","cta_text":"Request Pricing","intro":"","body":"","hero_image":"kerala-backwaters.jpg"}');
INSERT INTO page_content (page_key, title, sections_json) VALUES ('about', 'About YathraNest', '{"intro":"YathraNest crafts thoughtful journeys across Kerala, South India and beyond.","body":"<p>We plan packages, stays, taxi services and experiences with a simple rule: browse and enquire — pricing is shared personally for your dates.</p>","hero_image":"friends-travel.jpg"}');
INSERT INTO page_content (page_key, title, sections_json) VALUES ('faq', 'FAQ', '{"intro":"Common questions about planning with YathraNest.","body":"","faqs":[{"q":"Do you show prices online?","a":"No. We share personalised pricing after you enquire with dates and group size."},{"q":"Can you customise an itinerary?","a":"Yes. Share preferences and we will adjust stays, pace and inclusions."},{"q":"How do I book?","a":"Submit an enquiry. Our team confirms availability and sends a quote — no online payment required on this site."}]}');
INSERT INTO page_content (page_key, title, sections_json) VALUES ('terms', 'Terms & Conditions', '{"intro":"Please read these terms before enquiring.","body":"<p>Enquiries are requests for information and do not constitute a confirmed booking until written confirmation is issued by YathraNest.</p>"}');
INSERT INTO page_content (page_key, title, sections_json) VALUES ('privacy', 'Privacy Policy', '{"intro":"How we handle your enquiry details.","body":"<p>We use the contact information you submit solely to respond to your travel enquiry and related follow-ups. We do not sell personal data.</p>"}');
